result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/checks/codeowners_nonempty.py", "content": """"Check that a CODEOWNERS file exists and has at least one non-blank line."""

import os

CODEOWNERS_PATHS = [
    os.path.join(".github", "CODEOWNERS"),
    os.path.join("docs", "CODEOWNERS"),
    "CODEOWNERS",
]


def _has_content(path):
    try:
        with open(path, encoding="utf-8") as fh:
            return any(line.strip() for line in fh)
    except OSError:
        return False


def check(root):
    existing = [p for p in CODEOWNERS_PATHS if os.path.isfile(os.path.join(root, p))]
    if not existing:
        return {
            "status": "fail",
            "detail": "no CODEOWNERS file found (looked in .github/, docs/, repo root)",
        }
    with_content = [p for p in existing if _has_content(os.path.join(root, p))]
    if with_content:
        return {"status": "pass", "detail": "non-empty CODEOWNERS at " + with_content[0]}
    return {"status": "fail", "detail": "CODEOWNERS exists but contains no rules (" + ", ".join(existing) + ")"}
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/checks/ci_has_tests.py", "content": """"Check that some GitHub Actions workflow mentions pytest or npm test."""

import os

MARKERS = ("pytest", "npm test")


def _iter_workflows(root):
    wf_dir = os.path.join(root, ".github", "workflows")
    if not os.path.isdir(wf_dir):
        return []
    workflows = []
    for entry in sorted(os.listdir(wf_dir)):
        if entry.lower().endswith((".yml", ".yaml")):
            workflows.append(os.path.join(wf_dir, entry))
    return workflows


def check(root):
    for path in _iter_workflows(root):
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                content = fh.read()
        except OSError:
            continue
        for marker in MARKERS:
            if marker in content:
                rel = os.path.relpath(path, root)
                return {"status": "pass", "detail": f"'{marker}' found in {rel}"}
    if not _iter_workflows(root):
        return {"status": "fail", "detail": "no workflow files under .github/workflows/"}
    return {"status": "fail", "detail": "workflows exist but none run pytest or npm test"}
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/checks/readme_security_contact.py", "content": """"Check that the README declares a Security-Contact: line."""

import os


def _readme_path(root):
    for name in sorted(os.listdir(root), key=str.lower):
        lowered = name.lower()
        if lowered.startswith("readme") and lowered.endswith((".md", ".rst", ".txt", "")) and os.path.isfile(os.path.join(root, name)):
            return os.path.join(root, name)
    return None


def check(root):
    readme = _readme_path(root)
    if readme is None:
        return {"status": "fail", "detail": "no README file found at repo root"}
    try:
        with open(readme, encoding="utf-8", errors="replace") as fh:
            for line in fh:
                if line.strip().startswith("Security-Contact:"):
                    rel = os.path.relpath(readme, root)
                    return {"status": "pass", "detail": f"Security-Contact declared in {rel}"}
    except OSError:
        pass
    rel = os.path.relpath(readme, root)
    return {"status": "fail", "detail": f"{rel} has no line starting with 'Security-Contact:'"}
"})
